/* ---------- design tokens ---------- */
const C = {
  navy: "#0B1E36",
  navy2: "#122A47",
  charcoal: "#1C242E",
  gold: "#C6A15B",
  goldDark: "#A9843E",
  bg: "#F6F5F2",
  card: "#FFFFFF",
  line: "#E4E1D9",
  text: "#1C242E",
  sub: "#6B7280",
  green: "#1E8E5A",
  amber: "#B9760A",
  red: "#B3261E",
  blue: "#2E5FA3",
  grey: "#9AA1AC",
};

function Badge({ children, bg, fg }) {
  return (
    <span style={{
      background: bg, color: fg, fontSize: 11.5, fontWeight: 700,
      padding: "3px 9px", borderRadius: 999, letterSpacing: 0.2, whiteSpace: "nowrap",
      display: "inline-block",
    }}>{children}</span>
  );
}

function ReconIndicator({ color, label }) {
  const map = {
    green: { bg: "#E9F6EF", fg: C.green, dot: C.green },
    amber: { bg: "#FDF2E3", fg: C.amber, dot: C.amber },
    red: { bg: "#FCEAEA", fg: C.red, dot: C.red },
    grey: { bg: "#F0F0EF", fg: C.grey, dot: C.grey },
  };
  const m = map[color];
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 6, background: m.bg, color: m.fg, fontWeight: 700, fontSize: 12, padding: "4px 10px", borderRadius: 999 }}>
      <span style={{ width: 7, height: 7, borderRadius: 99, background: m.dot }} />
      {label}
    </span>
  );
}

export default function App() {
  const [role, setRole] = useState("President");
  const [tolerancePct, setTolerancePct] = useState(5);
  const [tab, setTab] = useState("dashboard");
  const [query, setQuery] = useState("");
  const [ceilOverrides, setCeilOverrides] = useState({});
  const HEADS = useMemo(
    () => BASE_HEADS.map((h) => ({ ...h, ceil: ceilOverrides[h.name] !== undefined ? ceilOverrides[h.name] : h.ceil })),
    [ceilOverrides]
  );
  const [selectedHead, setSelectedHead] = useState(HEADS[0].name);
  const [subCategoryFilter, setSubCategoryFilter] = useState("All");

  // working copy of items, enriched with mutable control fields
  const [items, setItems] = useState(() =>
    RAW_ITEMS.map((it) => ({
      ...it,
      committedQty: 0,
      committedVal: 0,
      approvalStatus: it.status === "Complete" ? "Approved" : "Pending",
      freezeState: "Not Frozen",
      deleted: false,
    }))
  );

  const [headFreeze, setHeadFreeze] = useState(() => {
    const o = {};
    HEADS.forEach((h) => (o[h.name] = "Not Frozen"));
    return o;
  });

  const [prs, setPrs] = useState([]);
  const [audit, setAudit] = useState(() => [
    { ts: nowStamp(), who: "System", text: `Imported ${RAW_ITEMS.length} line items from CPA_PRE_OPENING_CAPEX_WORKSHEET across 17 source sheets. Total approved operating-goods budget: ${fmtINR(TOTAL_BUDGET)}.` },
  ]);

  const logAudit = useCallback((text, who) => {
    setAudit((a) => [{ ts: nowStamp(), who: who || role, text }, ...a]);
  }, [role]);

  // per-head committed totals (from approved item values consumed by PRs)
  const COMMITTED_STATUSES = ["Auto-Approved", "President-Approved", "Ready for PO", "PO Issued", "Closed"];
  const headCommitted = useMemo(() => {
    const o = {};
    HEADS.forEach((h) => (o[h.name] = 0));
    items.forEach((it) => { if (!it.deleted) o[it.head] = (o[it.head] || 0) + (it.committedVal || 0); });
    prs.forEach((p) => {
      if (!p.itemId && p.headName && COMMITTED_STATUSES.includes(p.status)) {
        o[p.headName] = (o[p.headName] || 0) + (p.value || 0);
      }
    });
    return o;
  }, [items, prs]);

  const headItemTotal = useMemo(() => {
    const o = {};
    HEADS.forEach((h) => (o[h.name] = 0));
    items.forEach((it) => { if (!it.deleted) o[it.head] = (o[it.head] || 0) + (it.val || 0); });
    return o;
  }, [items]);

  const headIncomplete = useMemo(() => {
    const o = {};
    HEADS.forEach((h) => (o[h.name] = 0));
    items.forEach((it) => { if (!it.deleted && it.status !== "Complete") o[it.head] = (o[it.head] || 0) + 1; });
    return o;
  }, [items]);

  function reconColor(headName) {
    const state = headFreeze[headName];
    if (state === "Not Frozen") return "grey";
    const total = headItemTotal[headName];
    const ceil = HEADS.find((h) => h.name === headName).ceil;
    if (headIncomplete[headName] > 0 && state !== "Lump-Sum Frozen") return "amber";
    if (total > ceil) return "red";
    return "green";
  }

  const execTotals = useMemo(() => {
    let frozen = 0, provisional = 0, autoVal = 0, presVal = 0, committed = 0;
    HEADS.forEach((h) => {
      if (headFreeze[h.name] === "Fully Frozen") frozen += h.ceil;
      if (headFreeze[h.name] === "Provisionally Frozen") provisional += h.ceil;
    });
    prs.forEach((p) => {
      if (p.status === "Auto-Approved" || p.status.startsWith("Ready") || p.status === "PO Issued" || p.status === "Closed") autoVal += p.autoApproved ? p.value : 0;
      if (!p.autoApproved && (p.status === "President-Approved" || p.status === "Ready for PO" || p.status === "PO Issued" || p.status === "Closed")) presVal += p.value;
    });
    committed = Object.values(headCommitted).reduce((a, b) => a + b, 0);
    return { frozen, provisional, autoVal, presVal, committed };
  }, [headFreeze, prs, headCommitted]);
  /* ---------- actions ---------- */
  function updateItem(id, patch) {
    setItems((prev) => prev.map((it) => {
      if (it.id !== id) return it;
      const updated = { ...it, ...patch };
      if (patch.qty !== undefined || patch.rate !== undefined) {
        const q = patch.qty !== undefined ? patch.qty : it.qty;
        const r = patch.rate !== undefined ? patch.rate : it.rate;
        if (q !== null && r !== null && q !== "" && r !== "") {
          updated.val = Number(q) * Number(r);
          updated.status = "Complete";
        }
      }
      return updated;
    }));
  }

  function setItemApproval(id, status) {
    setItems((prev) => prev.map((it) => (it.id === id ? { ...it, approvalStatus: status } : it)));
    logAudit(`Item ${id} marked "${status}" during budget review.`);
  }

  function deleteItems(ids) {
    if (!ids.length) return;
    const names = items.filter((it) => ids.includes(it.id)).map((it) => it.name);
    setItems((prev) => prev.map((it) => (ids.includes(it.id) ? { ...it, deleted: true } : it)));
    logAudit(`Deleted ${ids.length} item(s): ${names.join(", ")}. Recoverable from Audit Trail via restore.`, "President (Arjun Arora)");
  }

  function restoreItem(id) {
    const it = items.find((i) => i.id === id);
    setItems((prev) => prev.map((i) => (i.id === id ? { ...i, deleted: false } : i)));
    logAudit(`Restored deleted item "${it ? it.name : id}".`, "President (Arjun Arora)");
  }

  function moveItemsToHead(ids, newHeadName) {
    if (!ids.length || !newHeadName) return;
    const newHead = HEADS.find((h) => h.name === newHeadName);
    const moved = items.filter((it) => ids.includes(it.id));
    const fromHeads = [...new Set(moved.map((it) => it.head))].join(", ");
    setItems((prev) => prev.map((it) => ids.includes(it.id) ? {
      ...it, head: newHeadName, dept: newHead.dept, ceil: newHead.ceil,
    } : it));
    logAudit(`Moved ${ids.length} item(s) from ${fromHeads} to "${newHeadName}": ${moved.map((it) => it.name).join(", ")}. Value counts against "${newHeadName}" ceiling immediately.`, "President (Arjun Arora)");
  }

  function renameItemName(id, newName) {
    setItems((prev) => prev.map((it) => (it.id === id ? { ...it, name: newName } : it)));
    logAudit(`Item ${id} renamed to "${newName}".`, "President (Arjun Arora)");
  }

  function renameCategoryBulk(ids, newCategory) {
    if (!ids.length || !newCategory) return;
    setItems((prev) => prev.map((it) => (ids.includes(it.id) ? { ...it, sub: newCategory } : it)));
    logAudit(`Renamed category to "${newCategory}" for ${ids.length} item(s).`, "President (Arjun Arora)");
  }

  function freezeHead(headName, state) {
    setHeadFreeze((prev) => ({ ...prev, [headName]: state }));
    setItems((prev) => prev.map((it) => (it.head === headName ? { ...it, freezeState: state } : it)));
    logAudit(`Budget head "${headName}" ${prev_action(state)}. Original approved values locked; a revision record will be created for any future edit.`, "President (Arjun Arora)");
  }
  function prev_action(state) {
    if (state === "Fully Frozen") return "FULLY FROZEN";
    if (state === "Provisionally Frozen") return "PROVISIONALLY FROZEN";
    if (state === "Lump-Sum Frozen") return "FROZEN AS LUMP-SUM (item-level PRs require case-by-case approval)";
    return "marked NOT APPROVED";
  }

  function setHeadCeiling(headName, newCeil) {
    const n = Number(newCeil);
    if (isNaN(n) || n < 0) return;
    setCeilOverrides((prev) => ({ ...prev, [headName]: n }));
    logAudit(`Budget head "${headName}" ceiling changed to ${fmtINR(n)}.`, "President (Arjun Arora)");
  }

  function submitPR({ itemId, requestedQty, requestedRate, requestedBy, dept, justification, urgency, requiredBy, unbudgetedName, unbudgetedHead, specChanged, brandChanged, vendorDetails, modelDetails, proposedBrand }) {
    const item = items.find((i) => i.id === itemId);
    const chargeHeadName = item ? item.head : unbudgetedHead;
    const head = { ceiling: HEADS.find((h) => h.name === chargeHeadName)?.ceil, committed: headCommitted[chargeHeadName] };
    let result;
    if (!item) {
      const catRemaining = (head.ceiling || 0) - (head.committed || 0);
      result = {
        decision: "escalate", reasonCode: "Unbudgeted Item",
        detail: `"${unbudgetedName}" does not exist anywhere in the frozen pre-opening item list. Requested to be charged against "${chargeHeadName}" (available balance: ${fmtINR(catRemaining)} of ${fmtINR(head.ceiling)}).`,
      };
    } else {
      result = evaluatePR(item, head, Number(requestedQty), Number(requestedRate), tolerancePct, specChanged, brandChanged);
    }
    const pr = {
      id: uid("PR"),
      itemId: item ? item.id : null,
      itemName: item ? item.name : unbudgetedName,
      headName: chargeHeadName,
      requestedQty: Number(requestedQty) || 0,
      requestedRate: Number(requestedRate) || 0,
      value: (Number(requestedQty) || 0) * (Number(requestedRate) || 0),
      requestedBy, dept, justification, urgency, requiredBy,
      vendorDetails: vendorDetails || "", modelDetails: modelDetails || "", proposedBrand: proposedBrand || "",
      submittedAt: nowStamp(),
      autoApproved: result.decision === "auto",
      status: result.decision === "auto" ? "Auto-Approved" : "Pending President",
      reasonCode: result.reasonCode,
      detail: result.detail,
      approvedQty: item ? item.qty : null,
      approvedRate: item ? item.rate : null,

      frozenSpec: item ? item.spec : null,
      decisionLog: [],
    };
    setPrs((prev) => [pr, ...prev]);
    if (result.decision === "auto" && item) {
      setItems((prev) => prev.map((it) => it.id === item.id ? {
        ...it,
        committedQty: (it.committedQty || 0) + pr.requestedQty,
        committedVal: (it.committedVal || 0) + pr.value,
      } : it));
      logAudit(`PR ${pr.id} for "${pr.itemName}" (${fmtNum(pr.requestedQty)} ${item.unit || "Nos"} @ ${fmtINR(pr.requestedRate)}) AUTO-APPROVED — within frozen pre-opening budget. Routed directly to Purchase Manager.`);
    } else {
      logAudit(`PR ${pr.id} for "${pr.itemName}" escalated to President — ${pr.reasonCode}.`);
    }
    return pr;
  }

  function presidentDecide(prId, decision, note) {
    setPrs((prev) => prev.map((p) => {
      if (p.id !== prId) return p;
      const approved = decision === "Approve" || decision === "Approve with Conditions" || decision === "Approve Revised Quantity" || decision === "Approve Revised Rate" || decision === "Approve Budget Transfer";
      const newStatus = approved ? "President-Approved" : (decision === "Reject" ? "Rejected" : decision === "Defer" ? "Deferred" : "Returned for Clarification");
      if (approved) {
        setItems((prevItems) => prevItems.map((it) => it.id === p.itemId ? {
          ...it,
          committedQty: (it.committedQty || 0) + p.requestedQty,
          committedVal: (it.committedVal || 0) + p.value,
        } : it));
      }
      logAudit(`President decision on PR ${p.id} ("${p.itemName}"): ${decision}${note ? " — " + note : ""}.`, "President (Arjun Arora)");
      return { ...p, status: newStatus, decisionLog: [...p.decisionLog, { decision, note, ts: nowStamp() }] };
    }));
  }

  function purchaseAdvance(prId, newStatus) {
    setPrs((prev) => prev.map((p) => p.id === prId ? { ...p, status: newStatus } : p));
    logAudit(`PR moved to "${newStatus}" by Purchase Manager.`);
  }

  const subCategoryOptions = useMemo(() => {
    const set = new Set();
    items.forEach((it) => { if (it.head === selectedHead && !it.deleted) set.add(it.sub && it.sub.trim() ? it.sub : "Uncategorized"); });
    return ["All", ...[...set].sort()];
  }, [items, selectedHead]);

  const filteredItems = useMemo(() => {
    let list = items.filter((it) => it.head === selectedHead && !it.deleted);
    if (subCategoryFilter !== "All") {
      list = list.filter((it) => (it.sub && it.sub.trim() ? it.sub : "Uncategorized") === subCategoryFilter);
    }
    if (query.trim()) {
      const q = query.toLowerCase();
      list = list.filter((it) => it.name.toLowerCase().includes(q) || (it.sub || "").toLowerCase().includes(q));
    }
    return list;
  }, [items, selectedHead, query, subCategoryFilter]);

  React.useEffect(() => { setSubCategoryFilter("All"); }, [selectedHead]);

  const deletedItemsForHead = useMemo(() =>
    items.filter((it) => it.head === selectedHead && it.deleted),
    [items, selectedHead]
  );

  const frozenItemsForPR = useMemo(() =>
    items.filter((it) => !it.deleted && it.freezeState !== "Not Frozen" && it.approvalStatus === "Approved" && it.status === "Complete"),
    [items]
  );

  const pendingExceptions = prs.filter((p) => p.status === "Pending President");
  /* ---------- shared bits ---------- */
  const TABS = [
    { id: "dashboard", label: "Executive Dashboard", roles: ["President", "Purchase Manager", "Department Head"] },
    { id: "freeze", label: "Budget Review & Freeze", roles: ["President"] },
    { id: "raisepr", label: "Raise Purchase Requisition", roles: ["Department Head", "President"] },
    { id: "queue", label: "Purchase Manager Queue", roles: ["Purchase Manager", "President"] },
    { id: "exceptions", label: "President's Exception Desk", roles: ["President"] },
    { id: "audit", label: "Audit Trail", roles: ["President", "Purchase Manager", "Department Head"] },
    { id: "demo", label: "Demo Scenarios", roles: ["President", "Purchase Manager", "Department Head"] },
  ];
  const visibleTabs = TABS.filter((t) => t.roles.includes(role));

  const cardStyle = { background: C.card, border: `1px solid ${C.line}`, borderRadius: 12, padding: 18 };

  return (
    <div style={{ fontFamily: "'Segoe UI', Inter, system-ui, sans-serif", background: C.bg, color: C.text, minHeight: "100%", fontSize: 14 }}>
      {/* HEADER */}
      <div style={{ background: `linear-gradient(120deg, ${C.navy}, ${C.navy2})`, color: "#fff", padding: "20px 28px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 14 }}>
          <div>
            <div style={{ fontSize: 11, letterSpacing: 2, color: C.gold, fontWeight: 700, textTransform: "uppercase" }}>Centre Point Hospitality</div>
            <div style={{ fontSize: 22, fontWeight: 700, marginTop: 2 }}>Centre Point Amravati — Pre-Opening Budget &amp; Purchase Control</div>
            <div style={{ fontSize: 12.5, color: "#C7D0DE", marginTop: 4 }}>
              Operating Goods Budget · Owner &amp; Final Exception Approver: <b style={{ color: "#fff" }}>Arjun Arora, President</b> · Source: CPA_PRE_OPENING_CAPEX_WORKSHEET_1
            </div>
          </div>
          <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
            <div style={{ textAlign: "right", marginRight: 6 }}>
              <div style={{ fontSize: 10, color: "#9FB0C7", letterSpacing: 1 }}>ROLE VIEW</div>
              <select value={role} onChange={(e) => { setRole(e.target.value); setTab("dashboard"); }}
                style={{ background: "#0E2743", color: "#fff", border: `1px solid ${C.gold}`, borderRadius: 8, padding: "7px 10px", fontSize: 13, fontWeight: 600 }}>
                <option>President</option>
                <option>Purchase Manager</option>
                <option>Department Head</option>
              </select>
            </div>
          </div>
        </div>
        {/* nav */}
        <div style={{ display: "flex", gap: 4, marginTop: 18, flexWrap: "wrap" }}>
          {visibleTabs.map((t) => (
            <button key={t.id} onClick={() => setTab(t.id)}
              style={{
                background: tab === t.id ? C.gold : "rgba(255,255,255,0.08)",
                color: tab === t.id ? C.navy : "#E8ECF3",
                border: "none", borderRadius: 8, padding: "8px 14px", fontSize: 12.5, fontWeight: 700, cursor: "pointer",
              }}>{t.label}{t.id === "exceptions" && pendingExceptions.length > 0 ? ` (${pendingExceptions.length})` : ""}</button>
          ))}
        </div>
      </div>

      <div style={{ padding: 22, maxWidth: 1400, margin: "0 auto" }}>
        {tab === "dashboard" && (
          <DashboardTab {...{ HEADS, headFreeze, headItemTotal, headCommitted, headIncomplete, reconColor, execTotals, prs, cardStyle, items, setTab, setSelectedHead }} />
        )}
        {tab === "freeze" && role === "President" && (
          <FreezeTab {...{ HEADS, headFreeze, freezeHead, selectedHead, setSelectedHead, filteredItems, deletedItemsForHead, updateItem, setItemApproval, query, setQuery, subCategoryFilter, setSubCategoryFilter, subCategoryOptions, cardStyle, reconColor, headItemTotal, headIncomplete, headCommitted, tolerancePct, setTolerancePct, setHeadCeiling, deleteItems, restoreItem, moveItemsToHead, renameItemName, renameCategoryBulk }} />
        )}
        {tab === "raisepr" && (
          <RaisePRTab {...{ HEADS, frozenItemsForPR, submitPR, cardStyle, tolerancePct, role }} />
        )}
        {tab === "queue" && (
          <QueueTab {...{ prs, purchaseAdvance, cardStyle }} />
        )}
        {tab === "exceptions" && role === "President" && (
          <ExceptionsTab {...{ pendingExceptions, presidentDecide, cardStyle, headCommitted, HEADS }} />
        )}
        {tab === "audit" && (
          <AuditTab {...{ audit, cardStyle }} />
        )}
        {tab === "demo" && (
          <DemoTab {...{ items, HEADS, headFreeze, freezeHead, setItemApproval, submitPR, setTab, cardStyle, tolerancePct }} />
        )}
      </div>
    </div>
  );
}
/* ================= DASHBOARD ================= */
function DashboardTab({ HEADS, headFreeze, headItemTotal, headCommitted, headIncomplete, reconColor, execTotals, prs, cardStyle, items, setTab, setSelectedHead }) {
  const autoCount = prs.filter((p) => p.autoApproved).length;
  const exCount = prs.filter((p) => !p.autoApproved).length;
  const pendingCount = prs.filter((p) => p.status === "Pending President").length;
  const totalCommitted = Object.values(headCommitted).reduce((a, b) => a + b, 0);
  const rateAbove5 = prs.filter((p) => p.reasonCode === "Rate Exceeds Approved Rate").length;
  const unbudgeted = prs.filter((p) => p.reasonCode === "Unbudgeted Item").length;
  const KpiCard = ({ label, value, sub, accent }) => (
    <div style={{ ...cardStyle, flex: "1 1 200px", minWidth: 190 }}>
      <div style={{ fontSize: 11, color: "#6B7280", fontWeight: 700, letterSpacing: 0.5, textTransform: "uppercase" }}>{label}</div>
      <div style={{ fontSize: 22, fontWeight: 800, marginTop: 6, color: accent || "#1C242E" }}>{value}</div>
      {sub && <div style={{ fontSize: 11.5, color: "#9AA1AC", marginTop: 3 }}>{sub}</div>}
    </div>
  );
  return (
    <div>
      <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginBottom: 16 }}>
        <KpiCard label="Total Approved Budget" value={fmtINR(19058140)} />
        <KpiCard label="Committed (Auto + President PRs)" value={fmtINR(totalCommitted)} accent="#2E5FA3" />
        <KpiCard label="Available Balance" value={fmtINR(19058140 - totalCommitted)} accent="#1E8E5A" />
        <KpiCard label="Pending Exceptions" value={pendingCount} accent={pendingCount ? "#B3261E" : "#1E8E5A"} sub="On President's desk right now" />
        <KpiCard label="Auto-Approved PRs" value={autoCount} accent="#1E8E5A" />
        <KpiCard label="President-Routed Exceptions" value={exCount} accent="#B9760A" />
        <KpiCard label="Unbudgeted Requests" value={unbudgeted} />
        <KpiCard label="Rate Variations Above Tolerance" value={rateAbove5} />
      </div>

      <div style={{ ...cardStyle, marginBottom: 16 }}>
        <div style={{ fontWeight: 700, marginBottom: 12 }}>Budget Head vs Item List vs Committed</div>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ textAlign: "left", color: "#6B7280", fontSize: 11, textTransform: "uppercase", letterSpacing: 0.4 }}>
              <th style={{ padding: "6px 8px" }}>Budget Head</th>
              <th style={{ padding: "6px 8px" }}>Freeze Status</th>
              <th style={{ padding: "6px 8px", textAlign: "right" }}>Ceiling</th>
              <th style={{ padding: "6px 8px", textAlign: "right" }}>Item List Total</th>
              <th style={{ padding: "6px 8px", textAlign: "right" }}>Committed</th>
              <th style={{ padding: "6px 8px" }}>Incomplete Items</th>
              <th style={{ padding: "6px 8px" }}>Reconciliation</th>
            </tr>
          </thead>
          <tbody>
            {HEADS.map((h) => (
              <tr key={h.name} style={{ borderTop: "1px solid #EEEDE7", cursor: "pointer" }} onClick={() => { setSelectedHead(h.name); setTab("freeze"); }}>
                <td style={{ padding: "8px 8px", fontWeight: 600 }}>{h.name}<div style={{ fontSize: 11, color: "#9AA1AC", fontWeight: 400 }}>{h.dept}</div></td>
                <td style={{ padding: "8px 8px" }}>
                  <Badge bg={headFreeze[h.name] === "Not Frozen" ? "#F0F0EF" : "#EAF0FB"} fg={headFreeze[h.name] === "Not Frozen" ? "#9AA1AC" : "#2E5FA3"}>{headFreeze[h.name]}</Badge>
                </td>
                <td style={{ padding: "8px 8px", textAlign: "right" }}>{fmtINR(h.ceil)}</td>
                <td style={{ padding: "8px 8px", textAlign: "right" }}>{fmtINR(headItemTotal[h.name])}</td>
                <td style={{ padding: "8px 8px", textAlign: "right" }}>{fmtINR(headCommitted[h.name])}</td>
                <td style={{ padding: "8px 8px" }}>{headIncomplete[h.name] > 0 ? <Badge bg="#FDF2E3" fg="#B9760A">{headIncomplete[h.name]} item(s)</Badge> : <Badge bg="#E9F6EF" fg="#1E8E5A">None</Badge>}</td>
                <td style={{ padding: "8px 8px" }}><ReconIndicator color={reconColor(h.name)} label={reconColor(h.name) === "green" ? "Within Ceiling" : reconColor(h.name) === "amber" ? "Incomplete" : reconColor(h.name) === "red" ? "Exceeds Ceiling" : "Not Frozen"} /></td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr style={{ borderTop: `2px solid ${C.line}`, fontWeight: 800 }}>
              <td style={{ padding: "10px 8px" }}>GRAND TOTAL</td>
              <td />
              <td style={{ padding: "10px 8px", textAlign: "right" }}>{fmtINR(19058140)}</td>
              <td style={{ padding: "10px 8px", textAlign: "right" }}>{fmtINR(Object.values(headItemTotal).reduce((a, b) => a + b, 0))}</td>
              <td style={{ padding: "10px 8px", textAlign: "right" }}>{fmtINR(totalCommitted)}</td>
              <td /><td />
            </tr>
          </tfoot>
        </table>
        <div style={{ fontSize: 11.5, color: "#9AA1AC", marginTop: 8 }}>Click any row to jump to that head's Budget Review &amp; Freeze screen.</div>
      </div>

      <div style={{ ...cardStyle }}>
        <div style={{ fontWeight: 700, marginBottom: 10 }}>Recent PR Activity</div>
        {prs.length === 0 && <div style={{ color: "#9AA1AC", fontSize: 13 }}>No purchase requisitions raised yet. Try the "Raise Purchase Requisition" tab or the Demo Scenarios.</div>}
        {prs.slice(0, 8).map((p) => (
          <div key={p.id} style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderTop: "1px solid #EEEDE7", fontSize: 13 }}>
            <div><b>{p.id}</b> · {p.itemName} <span style={{ color: "#9AA1AC" }}>({p.headName})</span></div>
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              <span style={{ color: "#9AA1AC" }}>{fmtINR(p.value)}</span>
              <Badge bg={p.autoApproved ? "#E9F6EF" : p.status === "Pending President" ? "#FCEAEA" : "#EAF0FB"} fg={p.autoApproved ? "#1E8E5A" : p.status === "Pending President" ? "#B3261E" : "#2E5FA3"}>{p.status}</Badge>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
/* ================= BUDGET FREEZE ================= */
function FreezeTab({ HEADS, headFreeze, freezeHead, selectedHead, setSelectedHead, filteredItems, deletedItemsForHead, updateItem, setItemApproval, query, setQuery, subCategoryFilter, setSubCategoryFilter, subCategoryOptions, cardStyle, reconColor, headItemTotal, headIncomplete, headCommitted, tolerancePct, setTolerancePct, setHeadCeiling, deleteItems, restoreItem, moveItemsToHead, renameItemName, renameCategoryBulk }) {
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState(() => new Set());
  const [showDeleted, setShowDeleted] = useState(false);
  const [moveTarget, setMoveTarget] = useState("");
  const [categoryInput, setCategoryInput] = useState("");
  const PAGE_SIZE = 25;
  const head = HEADS.find((h) => h.name === selectedHead);
  const pageItems = filteredItems.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
  const totalPages = Math.max(1, Math.ceil(filteredItems.length / PAGE_SIZE));
  const frozen = headFreeze[selectedHead] !== "Not Frozen";
  const color = reconColor(selectedHead);
  const dupes = useMemo(() => {
    const counts = {};
    filteredItems.forEach((it) => { counts[it.name.toLowerCase()] = (counts[it.name.toLowerCase()] || 0) + 1; });
    return Object.keys(counts).filter((k) => counts[k] > 1);
  }, [filteredItems]);

  React.useEffect(() => { setPage(1); }, [subCategoryFilter, query, selectedHead]);

  function toggleSelect(id) {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }
  function toggleSelectAllPage() {
    setSelected((prev) => {
      const next = new Set(prev);
      const allSelected = pageItems.every((it) => next.has(it.id));
      pageItems.forEach((it) => { if (allSelected) next.delete(it.id); else next.add(it.id); });
      return next;
    });
  }
  const selectedIds = [...selected];
  function clearSelection() { setSelected(new Set()); }
  function handleBulkDelete() {
    deleteItems(selectedIds);
    clearSelection();
  }
  function handleBulkMove() {
    if (!moveTarget) return;
    moveItemsToHead(selectedIds, moveTarget);
    clearSelection();
    setMoveTarget("");
  }
  function handleBulkRenameCategory() {
    if (!categoryInput.trim()) return;
    renameCategoryBulk(selectedIds, categoryInput.trim());
    clearSelection();
    setCategoryInput("");
  }

  return (
    <div style={{ display: "flex", gap: 16 }}>
      {/* sidebar */}
      <div style={{ width: 260, flexShrink: 0 }}>
        <div style={{ ...cardStyle, padding: 10 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "#6B7280", padding: "4px 8px", textTransform: "uppercase" }}>Budget Heads</div>
          {HEADS.map((h) => (
            <div key={h.name} onClick={() => { setSelectedHead(h.name); setPage(1); }}
              style={{
                padding: "9px 10px", borderRadius: 8, cursor: "pointer", marginBottom: 2,
                background: h.name === selectedHead ? "#0B1E36" : "transparent",
                color: h.name === selectedHead ? "#fff" : C.text,
              }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ fontSize: 13, fontWeight: 600 }}>{h.name}</span>
                <span style={{ width: 7, height: 7, borderRadius: 99, background: { green: "#1E8E5A", amber: "#B9760A", red: "#B3261E", grey: "#9AA1AC" }[reconColor(h.name)] }} />
              </div>
              <div style={{ fontSize: 11, color: h.name === selectedHead ? "#C7D0DE" : "#9AA1AC" }}>{fmtINR(h.ceil)} ceiling</div>
            </div>
          ))}
        </div>
        <div style={{ ...cardStyle, marginTop: 12 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "#6B7280", textTransform: "uppercase", marginBottom: 8 }}>Admin Setting</div>
          <label style={{ fontSize: 12.5 }}>Auto-approval rate tolerance</label>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 4 }}>
            <input type="number" value={tolerancePct} onChange={(e) => setTolerancePct(Number(e.target.value))} style={{ width: 60, padding: "5px 7px", border: `1px solid ${C.line}`, borderRadius: 6 }} />
            <span style={{ fontSize: 13 }}>%</span>
          </div>
        </div>
      </div>

      {/* main */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ ...cardStyle, marginBottom: 14 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 10 }}>
            <div>
              <div style={{ fontSize: 17, fontWeight: 700 }}>{selectedHead}</div>
              <div style={{ fontSize: 12.5, color: "#9AA1AC" }}>{head.dept} · {filteredItems.length} line items imported from source workbook</div>
            </div>
            <ReconIndicator color={color} label={color === "green" ? "Item total ≤ ceiling" : color === "amber" ? "Item list incomplete" : color === "red" ? "Item total exceeds ceiling" : "Not yet frozen"} />
          </div>
          <div style={{ display: "flex", gap: 22, marginTop: 14, flexWrap: "wrap" }}>
            {frozen ? (
              <MiniStat label="Ceiling" value={fmtINR(head.ceil)} />
            ) : (
              <div>
                <div style={{ fontSize: 10.5, color: "#9AA1AC", textTransform: "uppercase", letterSpacing: 0.3 }}>Ceiling (editable)</div>
                <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
                  <span style={{ fontSize: 13 }}>₹</span>
                  <input key={selectedHead} type="number" defaultValue={head.ceil} onBlur={(e) => setHeadCeiling(selectedHead, e.target.value)}
                    style={{ width: 110, padding: "4px 6px", border: `1px solid ${C.line}`, borderRadius: 5, fontSize: 14, fontWeight: 700 }} />
                </div>
              </div>
            )}
            <MiniStat label="Item list total" value={fmtINR(headItemTotal[selectedHead])} />
            <MiniStat label="Variance" value={fmtINR(headItemTotal[selectedHead] - head.ceil)} accent={headItemTotal[selectedHead] > head.ceil ? "#B3261E" : "#1E8E5A"} />
            <MiniStat label="Incomplete items" value={headIncomplete[selectedHead]} accent={headIncomplete[selectedHead] ? "#B9760A" : "#1E8E5A"} />
            <MiniStat label="Duplicate names" value={dupes.length} accent={dupes.length ? "#B3261E" : "#1E8E5A"} />
            <MiniStat label="Committed so far" value={fmtINR(headCommitted[selectedHead])} />
          </div>

          {!frozen ? (
            <div style={{ marginTop: 16, paddingTop: 14, borderTop: `1px solid ${C.line}`, display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
              <span style={{ fontSize: 12.5, color: "#6B7280", marginRight: 4 }}>Freeze this budget head as:</span>
              <button onClick={() => freezeHead(selectedHead, "Fully Frozen")} style={btnStyle(C.green)}>Fully Frozen</button>
              <button onClick={() => freezeHead(selectedHead, "Provisionally Frozen")} style={btnStyle(C.amber)}>Provisionally Frozen</button>
              <button onClick={() => freezeHead(selectedHead, "Lump-Sum Frozen")} style={btnStyle(C.blue)}>Lump-Sum Frozen</button>
              <button onClick={() => freezeHead(selectedHead, "Not Approved")} style={btnStyle(C.red)}>Not Approved</button>
              {(headIncomplete[selectedHead] > 0 || headItemTotal[selectedHead] > head.ceil || dupes.length > 0) && (
                <span style={{ fontSize: 11.5, color: C.amber, marginLeft: 6 }}>⚠ Missing data, ceiling breach, or duplicates detected — review before freezing "Fully Frozen".</span>
              )}
            </div>
          ) : (
            <div style={{ marginTop: 16, paddingTop: 14, borderTop: `1px solid ${C.line}`, fontSize: 13 }}>
              <Badge bg="#EAF0FB" fg="#2E5FA3">{headFreeze[selectedHead]}</Badge>
              <span style={{ color: "#9AA1AC", marginLeft: 10 }}>Original values are locked. Purchase users cannot edit. </span>
              <button onClick={() => freezeHead(selectedHead, "Not Frozen")} style={{ ...btnStyle(C.grey), marginLeft: 8 }}>Unfreeze (creates revision)</button>
            </div>
          )}
        </div>

        {!frozen && selectedIds.length > 0 && (
          <div style={{ ...cardStyle, marginBottom: 14, background: "#FFFBF0", border: `1px solid ${C.gold}` }}>
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
              <Badge bg={C.gold} fg={C.navy}>{selectedIds.length} selected</Badge>
              <select value={moveTarget} onChange={(e) => setMoveTarget(e.target.value)} style={{ fontSize: 12.5, padding: "6px 8px", borderRadius: 6, border: `1px solid ${C.line}` }}>
                <option value="">Move to head…</option>
                {HEADS.filter((h) => h.name !== selectedHead).map((h) => <option key={h.name} value={h.name}>{h.name}</option>)}
              </select>
              <button onClick={handleBulkMove} disabled={!moveTarget} style={{ ...btnStyle(C.blue), opacity: moveTarget ? 1 : 0.5 }}>Move</button>
              <input placeholder="Rename category to…" value={categoryInput} onChange={(e) => setCategoryInput(e.target.value)}
                style={{ fontSize: 12.5, padding: "6px 8px", borderRadius: 6, border: `1px solid ${C.line}`, width: 180 }} />
              <button onClick={handleBulkRenameCategory} disabled={!categoryInput.trim()} style={{ ...btnStyle(C.navy), opacity: categoryInput.trim() ? 1 : 0.5 }}>Rename</button>
              <button onClick={handleBulkDelete} style={btnStyle(C.red)}>Delete selected</button>
              <button onClick={clearSelection} style={{ ...btnStyle(C.grey) }}>Clear</button>
            </div>
          </div>
        )}

        <div style={{ ...cardStyle, padding: 0, overflow: "hidden" }}>
          <div style={{ padding: 12, borderBottom: `1px solid ${C.line}`, display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
            <input placeholder="Search items in this head…" value={query} onChange={(e) => setQuery(e.target.value)}
              style={{ flex: 1, minWidth: 180, padding: "8px 10px", border: `1px solid ${C.line}`, borderRadius: 8, fontSize: 13 }} />
            <select value={subCategoryFilter} onChange={(e) => setSubCategoryFilter(e.target.value)}
              style={{ padding: "8px 10px", border: `1px solid ${C.line}`, borderRadius: 8, fontSize: 13, minWidth: 160 }}>
              {subCategoryOptions.map((s) => <option key={s} value={s}>{s === "All" ? "All categories" : s}</option>)}
            </select>
            {subCategoryFilter !== "All" && (
              <Badge bg="#EAF0FB" fg="#2E5FA3">{filteredItems.length} in "{subCategoryFilter}"</Badge>
            )}
            {deletedItemsForHead.length > 0 && (
              <button onClick={() => setShowDeleted((s) => !s)} style={{ ...pgBtn, whiteSpace: "nowrap" }}>
                {showDeleted ? "Hide" : "Show"} deleted ({deletedItemsForHead.length})
              </button>
            )}
          </div>
          {showDeleted && (
            <div style={{ padding: 12, background: "#FAFAF8", borderBottom: `1px solid ${C.line}` }}>
              {deletedItemsForHead.map((it) => (
                <div key={it.id} style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, padding: "5px 0" }}>
                  <span style={{ color: "#9AA1AC", textDecoration: "line-through" }}>{it.name}</span>
                  <button onClick={() => restoreItem(it.id)} style={{ ...pgBtn, padding: "3px 10px" }}>Restore</button>
                </div>
              ))}
            </div>
          )}
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
              <thead>
                <tr style={{ textAlign: "left", color: "#6B7280", fontSize: 10.5, textTransform: "uppercase", background: "#FAFAF8" }}>
                  {!frozen && <th style={th}><input type="checkbox" checked={pageItems.length > 0 && pageItems.every((it) => selected.has(it.id))} onChange={toggleSelectAllPage} /></th>}
                  <th style={th}>Item</th>
                  <th style={th}>Spec / Sub-category</th>
                  <th style={thR}>Qty</th>
                  <th style={thR}>Rate</th>
                  <th style={thR}>Value</th>
                  <th style={th}>Data Status</th>
                  <th style={th}>Approval</th>
                  <th style={th}>Remarks</th>
                </tr>
              </thead>
              <tbody>
                {pageItems.map((it) => (
                  <ItemRow key={it.id} it={it} updateItem={updateItem} setItemApproval={setItemApproval} frozen={frozen}
                    selected={selected.has(it.id)} onToggleSelect={() => toggleSelect(it.id)}
                    renameItemName={renameItemName} deleteItems={deleteItems} />
                ))}
              </tbody>
            </table>
          </div>
          <div style={{ padding: 10, display: "flex", justifyContent: "center", gap: 8, borderTop: `1px solid ${C.line}` }}>
            <button disabled={page <= 1} onClick={() => setPage((p) => p - 1)} style={pgBtn}>Prev</button>
            <span style={{ fontSize: 12, color: "#6B7280", alignSelf: "center" }}>Page {page} of {totalPages}</span>
            <button disabled={page >= totalPages} onClick={() => setPage((p) => p + 1)} style={pgBtn}>Next</button>
          </div>
        </div>
      </div>
    </div>
  );
}

function MiniStat({ label, value, accent }) {
  return (
    <div>
      <div style={{ fontSize: 10.5, color: "#9AA1AC", textTransform: "uppercase", letterSpacing: 0.3 }}>{label}</div>
      <div style={{ fontSize: 15, fontWeight: 700, color: accent || C.text }}>{value}</div>
    </div>
  );
}
const th = { padding: "8px 10px", whiteSpace: "nowrap" };
const thR = { padding: "8px 10px", textAlign: "right", whiteSpace: "nowrap" };
const pgBtn = { border: `1px solid ${C.line}`, background: "#fff", borderRadius: 6, padding: "5px 12px", fontSize: 12, cursor: "pointer" };
function btnStyle(color) {
  return { background: color, color: "#fff", border: "none", borderRadius: 7, padding: "8px 14px", fontSize: 12.5, fontWeight: 700, cursor: "pointer" };
}

function ItemRow({ it, updateItem, setItemApproval, frozen, selected, onToggleSelect, renameItemName, deleteItems }) {
  const sc = STATUS_COLORS[it.status] || STATUS_COLORS.Complete;
  return (
    <tr style={{ borderTop: "1px solid #F0EFEA", background: selected ? "#FFFBF0" : "transparent" }}>
      {!frozen && <td style={{ padding: "7px 6px" }}><input type="checkbox" checked={!!selected} onChange={onToggleSelect} /></td>}
      <td style={{ padding: "7px 10px", fontWeight: 600, maxWidth: 220 }}>
        {frozen ? it.name : (
          <input defaultValue={it.name} onBlur={(e) => e.target.value.trim() && e.target.value !== it.name && renameItemName(it.id, e.target.value.trim())}
            style={{ ...cellInput, width: "100%", fontWeight: 600, textAlign: "left" }} />
        )}
        {it.vq && Object.keys(it.vq).length > 0 && (
          <div style={{ fontSize: 10.5, color: "#9AA1AC", fontWeight: 400 }}>{Object.entries(it.vq).map(([v, d]) => `${v}: ₹${d.rate}`).join(" · ")}</div>
        )}
        {!frozen && <button onClick={() => deleteItems([it.id])} style={{ fontSize: 10.5, color: C.red, background: "none", border: "none", cursor: "pointer", padding: 0, marginTop: 3 }}>Delete</button>}
      </td>
      <td style={{ padding: "7px 10px", color: "#6B7280", maxWidth: 200 }}>
        {it.spec || (frozen ? (it.sub || "—") : (
          <input defaultValue={it.sub || ""} placeholder="category" onBlur={(e) => e.target.value !== it.sub && updateItem(it.id, { sub: e.target.value })}
            style={{ ...cellInput, width: "100%", textAlign: "left" }} />
        ))}
      </td>
      <td style={{ padding: "3px 6px", textAlign: "right" }}>
        {frozen ? fmtNum(it.qty) : <input disabled={frozen} defaultValue={it.qty ?? ""} onBlur={(e) => updateItem(it.id, { qty: e.target.value === "" ? null : Number(e.target.value) })} style={cellInput} />}
      </td>
      <td style={{ padding: "3px 6px", textAlign: "right" }}>
        {frozen ? fmtINR(it.rate) : <input disabled={frozen} defaultValue={it.rate ?? ""} onBlur={(e) => updateItem(it.id, { rate: e.target.value === "" ? null : Number(e.target.value) })} style={cellInput} />}
      </td>
      <td style={{ padding: "7px 10px", textAlign: "right", fontWeight: 600 }}>{fmtINR(it.val)}</td>
      <td style={{ padding: "7px 10px" }}><Badge bg={sc.bg} fg={sc.fg}>{sc.label}</Badge></td>
      <td style={{ padding: "7px 10px" }}>
        {frozen ? <Badge bg="#EAF0FB" fg="#2E5FA3">{it.approvalStatus}</Badge> : (
          <select disabled={frozen} value={it.approvalStatus} onChange={(e) => setItemApproval(it.id, e.target.value)} style={{ fontSize: 11.5, padding: "3px 5px", borderRadius: 5, border: `1px solid ${C.line}` }}>
            {APPROVAL_STATES.map((s) => <option key={s}>{s}</option>)}
          </select>
        )}
      </td>
      <td style={{ padding: "7px 10px", color: "#9AA1AC", maxWidth: 260, fontSize: 11.5 }}>{it.rem || "—"}</td>
    </tr>
  );
}
const cellInput = { width: 72, padding: "4px 6px", border: `1px solid ${C.line}`, borderRadius: 5, textAlign: "right", fontSize: 12 };
/* ================= RAISE PR (Purchasing Guideline) ================= */
function RaisePRTab({ HEADS, frozenItemsForPR, submitPR, cardStyle, tolerancePct, role }) {
  const [mode, setMode] = useState("single"); // single | bulk | unlisted

  const MODES = [
    { id: "single", label: "Single Order" },
    { id: "bulk", label: "Bulk Order" },
    { id: "unlisted", label: "Unlisted Item" },
  ];

  return (
    <div>
      <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
        {MODES.map((m) => (
          <button key={m.id} onClick={() => setMode(m.id)}
            style={{ ...toggleBtn, ...(mode === m.id ? toggleActive : {}), padding: "9px 18px", fontSize: 13 }}>
            {m.label}
          </button>
        ))}
      </div>
      {mode === "single" && <SingleOrderPanel {...{ HEADS, frozenItemsForPR, submitPR, cardStyle, tolerancePct, role }} />}
      {mode === "bulk" && <BulkOrderPanel {...{ HEADS, frozenItemsForPR, submitPR, cardStyle, tolerancePct, role }} />}
      {mode === "unlisted" && <UnlistedOrderPanel {...{ HEADS, submitPR, cardStyle, role }} />}
    </div>
  );
}

/* Shared item-picker table (used by Single and Bulk) */
function ItemPickerTable({ items, headFilter, setHeadFilter, HEADS, showHeadFilter, query, setQuery, page, setPage, pageSize, children, extraHeaderCols, renderRow }) {
  const totalPages = Math.max(1, Math.ceil(items.length / pageSize));
  const pageItems = items.slice((page - 1) * pageSize, page * pageSize);
  return (
    <div style={{ ...cardBase, padding: 0, overflow: "hidden" }}>
      <div style={{ padding: 12, borderBottom: `1px solid ${C.line}`, display: "flex", gap: 10, flexWrap: "wrap" }}>
        {showHeadFilter && (
          <select value={headFilter} onChange={(e) => setHeadFilter(e.target.value)} style={{ padding: "8px 10px", border: `1px solid ${C.line}`, borderRadius: 8, fontSize: 13, minWidth: 200 }}>
            {HEADS.map((h) => <option key={h.name} value={h.name}>{h.name}</option>)}
          </select>
        )}
        <input placeholder="Search items…" value={query} onChange={(e) => setQuery(e.target.value)}
          style={{ flex: 1, minWidth: 160, padding: "8px 10px", border: `1px solid ${C.line}`, borderRadius: 8, fontSize: 13 }} />
        <span style={{ alignSelf: "center", fontSize: 12, color: "#9AA1AC" }}>{items.length} frozen item(s) available</span>
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}>
          <thead>
            <tr style={{ textAlign: "left", color: "#6B7280", fontSize: 10.5, textTransform: "uppercase", background: "#FAFAF8" }}>
              {extraHeaderCols}
              <th style={th}>Item</th>
              <th style={th}>Head / Sub-category</th>
              <th style={thR}>Approved Qty</th>
              <th style={thR}>Balance</th>
              <th style={thR}>Rate</th>
              {children}
            </tr>
          </thead>
          <tbody>
            {pageItems.map((it) => renderRow(it))}
            {pageItems.length === 0 && (
              <tr><td colSpan={8} style={{ padding: 20, textAlign: "center", color: "#9AA1AC" }}>No frozen items match.</td></tr>
            )}
          </tbody>
        </table>
      </div>
      <div style={{ padding: 10, display: "flex", justifyContent: "center", gap: 8, borderTop: `1px solid ${C.line}` }}>
        <button disabled={page <= 1} onClick={() => setPage((p) => p - 1)} style={pgBtn}>Prev</button>
        <span style={{ fontSize: 12, color: "#6B7280", alignSelf: "center" }}>Page {page} of {totalPages}</span>
        <button disabled={page >= totalPages} onClick={() => setPage((p) => p + 1)} style={pgBtn}>Next</button>
      </div>
    </div>
  );
}
const cardBase = { background: C.card, border: `1px solid ${C.line}`, borderRadius: 12 };

/* ---------- SINGLE ORDER ---------- */
function SingleOrderPanel({ HEADS, frozenItemsForPR, submitPR, cardStyle, tolerancePct, role }) {
  const [headFilter, setHeadFilter] = useState("All");
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [selectedId, setSelectedId] = useState(null);

  const filtered = useMemo(() => {
    let list = frozenItemsForPR;
    if (headFilter !== "All") list = list.filter((it) => it.head === headFilter);
    if (query.trim()) {
      const q = query.toLowerCase();
      list = list.filter((it) => it.name.toLowerCase().includes(q) || (it.sub || "").toLowerCase().includes(q));
    }
    return list;
  }, [frozenItemsForPR, headFilter, query]);

  const item = frozenItemsForPR.find((it) => it.id === selectedId);

  return (
    <div style={{ display: "grid", gridTemplateColumns: item ? "1.2fr 0.8fr" : "1fr", gap: 16 }}>
      <ItemPickerTable
        items={filtered} headFilter={headFilter} setHeadFilter={(v) => { setHeadFilter(v); setPage(1); }}
        HEADS={[{ name: "All" }, ...HEADS]} showHeadFilter query={query} setQuery={(v) => { setQuery(v); setPage(1); }}
        page={page} setPage={setPage} pageSize={12}
        renderRow={(it) => (
          <tr key={it.id} onClick={() => setSelectedId(it.id)}
            style={{ borderTop: "1px solid #F0EFEA", cursor: "pointer", background: selectedId === it.id ? "#FFFBF0" : "transparent" }}>
            <td style={{ padding: "8px 10px", fontWeight: 600 }}>{it.name}</td>
            <td style={{ padding: "8px 10px", color: "#6B7280" }}>{it.head}{it.sub ? ` · ${it.sub}` : ""}</td>
            <td style={{ padding: "8px 10px", textAlign: "right" }}>{fmtNum(it.qty)} {it.unit}</td>
            <td style={{ padding: "8px 10px", textAlign: "right" }}>{fmtNum(it.qty - (it.committedQty || 0))}</td>
            <td style={{ padding: "8px 10px", textAlign: "right" }}>{fmtINR(it.rate)}</td>
          </tr>
        )}
      />
      {item && (
        <SingleOrderForm key={item.id} item={item} submitPR={submitPR} cardStyle={cardStyle} tolerancePct={tolerancePct} role={role} onClose={() => setSelectedId(null)} />
      )}
    </div>
  );
}

function SingleOrderForm({ item, submitPR, cardStyle, tolerancePct, role, onClose }) {
  const [qty, setQty] = useState("");
  const [rate, setRate] = useState(item.rate);
  const [requestedBy, setRequestedBy] = useState("");
  const [dept, setDept] = useState("");
  const [justification, setJustification] = useState("");
  const [urgency, setUrgency] = useState("Normal");
  const [requiredBy, setRequiredBy] = useState("");
  const [specChanged, setSpecChanged] = useState(false);
  const [brandChanged, setBrandChanged] = useState(false);
  const [vendorDetails, setVendorDetails] = useState("");
  const [modelDetails, setModelDetails] = useState("");
  const [proposedBrand, setProposedBrand] = useState("");
  const [lastResult, setLastResult] = useState(null);

  const remainingQty = item.qty - (item.committedQty || 0);
  const maxRate = item.rate * (1 + tolerancePct / 100);

  function handleSubmit() {
    const pr = submitPR({
      itemId: item.id, requestedQty: qty, requestedRate: rate,
      requestedBy, dept, justification, urgency, requiredBy, specChanged, brandChanged,
      vendorDetails, modelDetails, proposedBrand,
    });
    setLastResult(pr);
  }

  return (
    <div>
      <div style={{ ...cardStyle, marginBottom: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div>
            <div style={{ fontWeight: 700 }}>{item.name}</div>
            <div style={{ fontSize: 12, color: "#9AA1AC" }}>{item.head}{item.sub ? ` · ${item.sub}` : ""}</div>
          </div>
          <button onClick={onClose} style={{ ...pgBtn, padding: "3px 10px" }}>✕</button>
        </div>
        <div style={{ background: "#FAFAF8", border: `1px solid ${C.line}`, borderRadius: 8, padding: 10, marginTop: 10, fontSize: 12.5 }}>
          <div>Approved qty: <b>{fmtNum(item.qty)} {item.unit}</b> · Remaining balance: <b>{fmtNum(remainingQty)}</b></div>
          <div>Approved rate: <b>{fmtINR(item.rate)}</b> · Max under {tolerancePct}% tolerance: <b>{fmtINR(maxRate)}</b></div>
          <div>Committed so far: <b>{fmtINR(item.committedVal)}</b></div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginTop: 12 }}>
          <Field label="Requested quantity"><input type="number" value={qty} onChange={(e) => setQty(e.target.value)} style={inputStyle} /></Field>
          <Field label="Proposed rate (₹)"><input type="number" value={rate} onChange={(e) => setRate(e.target.value)} style={inputStyle} /></Field>
          <Field label="Requested by"><input value={requestedBy} onChange={(e) => setRequestedBy(e.target.value)} style={inputStyle} /></Field>
          <Field label="Department"><input value={dept} onChange={(e) => setDept(e.target.value)} style={inputStyle} /></Field>
          <Field label="Urgency">
            <select value={urgency} onChange={(e) => setUrgency(e.target.value)} style={inputStyle}>
              <option>Normal</option><option>High — opening critical</option><option>Low</option>
            </select>
          </Field>
          <Field label="Required-by date"><input type="date" value={requiredBy} onChange={(e) => setRequiredBy(e.target.value)} style={inputStyle} /></Field>
        </div>
        <Field label="Operational justification"><textarea value={justification} onChange={(e) => setJustification(e.target.value)} style={{ ...inputStyle, minHeight: 50 }} /></Field>
        <div style={{ fontSize: 11, fontWeight: 700, color: "#6B7280", textTransform: "uppercase", letterSpacing: 0.4, margin: "10px 0 8px", paddingTop: 8, borderTop: `1px solid ${C.line}` }}>Vendor &amp; Item Detail</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <Field label="Vendor / supplier"><input value={vendorDetails} onChange={(e) => setVendorDetails(e.target.value)} style={inputStyle} /></Field>
          <Field label="Proposed brand"><input value={proposedBrand} onChange={(e) => setProposedBrand(e.target.value)} style={inputStyle} /></Field>
        </div>
        <Field label="Model no. / specific item details"><textarea value={modelDetails} onChange={(e) => setModelDetails(e.target.value)} style={{ ...inputStyle, minHeight: 40 }} /></Field>
        <div style={{ display: "flex", gap: 16, marginBottom: 12 }}>
          <label style={{ fontSize: 12, display: "flex", gap: 6, alignItems: "center" }}><input type="checkbox" checked={specChanged} onChange={(e) => setSpecChanged(e.target.checked)} /> Spec differs</label>
          <label style={{ fontSize: 12, display: "flex", gap: 6, alignItems: "center" }}><input type="checkbox" checked={brandChanged} onChange={(e) => setBrandChanged(e.target.checked)} /> Brand differs</label>
        </div>
        <button onClick={handleSubmit} disabled={!qty || !rate} style={{ ...btnStyle(C.navy), opacity: (!qty || !rate) ? 0.5 : 1 }}>Submit Purchase Requisition</button>
      </div>
      {lastResult && <ResultPanel result={lastResult} cardStyle={cardStyle} />}
    </div>
  );
}

/* ---------- BULK ORDER ---------- */
function BulkOrderPanel({ HEADS, frozenItemsForPR, submitPR, cardStyle, tolerancePct, role }) {
  const [headFilter, setHeadFilter] = useState(HEADS[0].name);
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [rows, setRows] = useState({}); // id -> {checked, qty, rate}
  const [requestedBy, setRequestedBy] = useState("");
  const [dept, setDept] = useState("");
  const [justification, setJustification] = useState("");
  const [urgency, setUrgency] = useState("Normal");
  const [requiredBy, setRequiredBy] = useState("");
  const [vendorDetails, setVendorDetails] = useState("");
  const [modelDetails, setModelDetails] = useState("");
  const [proposedBrand, setProposedBrand] = useState("");
  const [batchResults, setBatchResults] = useState(null);

  const items = useMemo(() => {
    let list = frozenItemsForPR.filter((it) => it.head === headFilter);
    if (query.trim()) {
      const q = query.toLowerCase();
      list = list.filter((it) => it.name.toLowerCase().includes(q) || (it.sub || "").toLowerCase().includes(q));
    }
    return list;
  }, [frozenItemsForPR, headFilter, query]);

  function setRow(id, patch) {
    setRows((prev) => ({ ...prev, [id]: { checked: false, qty: "", rate: "", ...prev[id], ...patch } }));
  }
  const selectedIds = Object.keys(rows).filter((id) => rows[id]?.checked);
  const selectedCount = selectedIds.length;
  const readyCount = selectedIds.filter((id) => rows[id].qty && rows[id].rate).length;
  const allReady = selectedCount > 0 && readyCount === selectedCount;

  function handleSubmitBulk() {
    const results = selectedIds.map((id) => {
      return submitPR({
        itemId: id, requestedQty: rows[id].qty, requestedRate: rows[id].rate,
        requestedBy, dept, justification, urgency, requiredBy, vendorDetails, modelDetails, proposedBrand,
      });
    });
    setBatchResults(results);
    setRows({});
  }

  return (
    <div>
      <div style={{ ...cardStyle, marginBottom: 14 }}>
        <div style={{ fontWeight: 700, marginBottom: 4 }}>Bulk order details (applied to every item in this batch)</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 10, marginTop: 8 }}>
          <Field label="Requested by"><input value={requestedBy} onChange={(e) => setRequestedBy(e.target.value)} style={inputStyle} /></Field>
          <Field label="Department"><input value={dept} onChange={(e) => setDept(e.target.value)} style={inputStyle} /></Field>
          <Field label="Urgency">
            <select value={urgency} onChange={(e) => setUrgency(e.target.value)} style={inputStyle}>
              <option>Normal</option><option>High — opening critical</option><option>Low</option>
            </select>
          </Field>
          <Field label="Required-by date"><input type="date" value={requiredBy} onChange={(e) => setRequiredBy(e.target.value)} style={inputStyle} /></Field>
        </div>
        <Field label="Operational justification"><textarea value={justification} onChange={(e) => setJustification(e.target.value)} style={{ ...inputStyle, minHeight: 44 }} /></Field>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10 }}>
          <Field label="Vendor / supplier"><input value={vendorDetails} onChange={(e) => setVendorDetails(e.target.value)} style={inputStyle} /></Field>
          <Field label="Proposed brand"><input value={proposedBrand} onChange={(e) => setProposedBrand(e.target.value)} style={inputStyle} /></Field>
          <Field label="Model no. / item details"><input value={modelDetails} onChange={(e) => setModelDetails(e.target.value)} style={inputStyle} /></Field>
        </div>
      </div>

      <ItemPickerTable
        items={items} headFilter={headFilter} setHeadFilter={(v) => { setHeadFilter(v); setPage(1); }}
        HEADS={HEADS} showHeadFilter query={query} setQuery={(v) => { setQuery(v); setPage(1); }}
        page={page} setPage={setPage} pageSize={12}
        extraHeaderCols={<th style={th}><input type="checkbox" onChange={(e) => {
          const checked = e.target.checked;
          const patch = {};
          items.slice((page - 1) * 12, page * 12).forEach((it) => { patch[it.id] = { ...(rows[it.id] || {}), checked }; });
          setRows((prev) => ({ ...prev, ...patch }));
        }} /></th>}
        renderRow={(it) => {
          const row = rows[it.id] || { checked: false, qty: "", rate: "" };
          return (
            <tr key={it.id} style={{ borderTop: "1px solid #F0EFEA", background: row.checked ? "#FFFBF0" : "transparent" }}>
              <td style={{ padding: "6px 10px" }}><input type="checkbox" checked={row.checked} onChange={(e) => setRow(it.id, { checked: e.target.checked })} /></td>
              <td style={{ padding: "6px 10px", fontWeight: 600 }}>{it.name}</td>
              <td style={{ padding: "6px 10px", color: "#6B7280" }}>{it.head}{it.sub ? ` · ${it.sub}` : ""}</td>
              <td style={{ padding: "6px 10px", textAlign: "right" }}>{fmtNum(it.qty)} {it.unit}</td>
              <td style={{ padding: "6px 10px", textAlign: "right" }}>{fmtNum(it.qty - (it.committedQty || 0))}</td>
              <td style={{ padding: "6px 10px", textAlign: "right" }}>{fmtINR(it.rate)}</td>
              <td style={{ padding: "6px 6px" }}>
                <input type="number" placeholder="Qty" disabled={!row.checked} value={row.qty} onChange={(e) => setRow(it.id, { qty: e.target.value })} style={{ ...cellInput, width: 70, background: row.checked ? "#fff" : "#F5F5F3" }} />
              </td>
              <td style={{ padding: "6px 6px" }}>
                <input type="number" placeholder="Rate" disabled={!row.checked} value={row.rate} onChange={(e) => setRow(it.id, { rate: e.target.value })} style={{ ...cellInput, width: 80, background: row.checked ? "#fff" : "#F5F5F3" }} />
              </td>
            </tr>
          );
        }}
      >
        <th style={thR}>Req. Qty</th>
        <th style={thR}>Req. Rate</th>
      </ItemPickerTable>

      <div style={{ ...cardStyle, marginTop: 14, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10 }}>
        <div style={{ fontSize: 12.5, color: "#6B7280" }}>
          {selectedCount === 0 ? "No items selected." : `${selectedCount} item(s) selected — ${readyCount} have qty & rate filled in.`}
        </div>
        <button onClick={handleSubmitBulk} disabled={!allReady} style={{ ...btnStyle(C.navy), opacity: allReady ? 1 : 0.5 }}>
          Submit Bulk Order ({selectedCount})
        </button>
      </div>

      {batchResults && (
        <div style={{ ...cardStyle, marginTop: 14 }}>
          <div style={{ fontWeight: 700, marginBottom: 10 }}>
            Batch result: {batchResults.filter((r) => r.autoApproved).length} auto-approved, {batchResults.filter((r) => !r.autoApproved).length} escalated to President
          </div>
          {batchResults.map((r) => (
            <div key={r.id} style={{ display: "flex", justifyContent: "space-between", padding: "8px 0", borderTop: "1px solid #F0EFEA", fontSize: 12.5 }}>
              <div>{r.itemName} <span style={{ color: "#9AA1AC" }}>({fmtNum(r.requestedQty)} @ {fmtINR(r.requestedRate)})</span></div>
              <Badge bg={r.autoApproved ? "#E9F6EF" : "#FCEAEA"} fg={r.autoApproved ? C.green : C.red}>{r.autoApproved ? "AUTO-APPROVED" : r.reasonCode}</Badge>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ---------- UNLISTED ITEM ---------- */
function UnlistedOrderPanel({ HEADS, submitPR, cardStyle, role }) {
  const [unbudgetedName, setUnbudgetedName] = useState("");
  const [unbudgetedHead, setUnbudgetedHead] = useState("");
  const [qty, setQty] = useState("");
  const [rate, setRate] = useState("");
  const [requestedBy, setRequestedBy] = useState("");
  const [dept, setDept] = useState("");
  const [justification, setJustification] = useState("");
  const [urgency, setUrgency] = useState("Normal");
  const [requiredBy, setRequiredBy] = useState("");
  const [vendorDetails, setVendorDetails] = useState("");
  const [modelDetails, setModelDetails] = useState("");
  const [proposedBrand, setProposedBrand] = useState("");
  const [lastResult, setLastResult] = useState(null);

  function handleSubmit() {
    const pr = submitPR({
      itemId: null, requestedQty: qty, requestedRate: rate, requestedBy, dept, justification, urgency, requiredBy,
      unbudgetedName, unbudgetedHead, vendorDetails, modelDetails, proposedBrand,
    });
    setLastResult(pr);
  }

  const disabled = !unbudgetedName || !unbudgetedHead || !qty || !rate;

  return (
    <div style={{ display: "grid", gridTemplateColumns: "1.2fr 0.8fr", gap: 16 }}>
      <div style={{ ...cardStyle }}>
        <div style={{ fontWeight: 700, marginBottom: 4 }}>Raise a requisition for an item not in the frozen list</div>
        <div style={{ fontSize: 12.5, color: "#9AA1AC", marginBottom: 14 }}>This will always be escalated to the President — an unlisted item can never auto-approve.</div>
        <Field label="Item name"><input value={unbudgetedName} onChange={(e) => setUnbudgetedName(e.target.value)} style={inputStyle} placeholder="e.g. Extra buffet chafing dish set" /></Field>
        <Field label="Budget head to charge (required)">
          <select value={unbudgetedHead} onChange={(e) => setUnbudgetedHead(e.target.value)} style={inputStyle}>
            <option value="">— select the budget head this will draw from —</option>
            {HEADS.map((h) => <option key={h.name} value={h.name}>{h.name}</option>)}
          </select>
        </Field>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <Field label="Requested quantity"><input type="number" value={qty} onChange={(e) => setQty(e.target.value)} style={inputStyle} /></Field>
          <Field label="Proposed rate (₹)"><input type="number" value={rate} onChange={(e) => setRate(e.target.value)} style={inputStyle} /></Field>
          <Field label="Requested by"><input value={requestedBy} onChange={(e) => setRequestedBy(e.target.value)} style={inputStyle} /></Field>
          <Field label="Department"><input value={dept} onChange={(e) => setDept(e.target.value)} style={inputStyle} /></Field>
          <Field label="Urgency">
            <select value={urgency} onChange={(e) => setUrgency(e.target.value)} style={inputStyle}>
              <option>Normal</option><option>High — opening critical</option><option>Low</option>
            </select>
          </Field>
          <Field label="Required-by date"><input type="date" value={requiredBy} onChange={(e) => setRequiredBy(e.target.value)} style={inputStyle} /></Field>
        </div>
        <Field label="Operational justification"><textarea value={justification} onChange={(e) => setJustification(e.target.value)} style={{ ...inputStyle, minHeight: 50 }} /></Field>
        <div style={{ fontSize: 11, fontWeight: 700, color: "#6B7280", textTransform: "uppercase", letterSpacing: 0.4, margin: "10px 0 8px", paddingTop: 8, borderTop: `1px solid ${C.line}` }}>Vendor &amp; Item Detail</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <Field label="Vendor / supplier"><input value={vendorDetails} onChange={(e) => setVendorDetails(e.target.value)} style={inputStyle} /></Field>
          <Field label="Proposed brand"><input value={proposedBrand} onChange={(e) => setProposedBrand(e.target.value)} style={inputStyle} /></Field>
        </div>
        <Field label="Model no. / specific item details"><textarea value={modelDetails} onChange={(e) => setModelDetails(e.target.value)} style={{ ...inputStyle, minHeight: 40 }} /></Field>
        <button onClick={handleSubmit} disabled={disabled} style={{ ...btnStyle(C.navy), opacity: disabled ? 0.5 : 1 }}>Submit Purchase Requisition</button>
      </div>
      {lastResult && <ResultPanel result={lastResult} cardStyle={cardStyle} />}
    </div>
  );
}

function ResultPanel({ result, cardStyle }) {
  return (
    <div style={{ ...cardStyle, position: "sticky", top: 16, alignSelf: "start" }}>
      <div style={{ fontWeight: 700, marginBottom: 10 }}>Result</div>
      {result.autoApproved ? (
        <div style={{ background: "#E9F6EF", border: "1px solid #BFE6D2", borderRadius: 8, padding: 12 }}>
          <div style={{ fontWeight: 800, color: C.green, fontSize: 13 }}>✓ AUTO-APPROVED — WITHIN FROZEN PRE-OPENING BUDGET</div>
          <div style={{ fontSize: 12, marginTop: 6, color: "#2A5F45" }}>{result.detail}</div>
          <div style={{ fontSize: 12, marginTop: 6 }}>Routed directly to Purchase Manager. No President / GM / Finance approval required.</div>
        </div>
      ) : (
        <div style={{ background: "#FCEAEA", border: "1px solid #F2C5C2", borderRadius: 8, padding: 12 }}>
          <div style={{ fontWeight: 800, color: C.red, fontSize: 13 }}>⤴ ESCALATED TO PRESIDENT</div>
          <div style={{ fontSize: 12.5, marginTop: 6, fontWeight: 700 }}>{result.reasonCode}</div>
          <div style={{ fontSize: 12, marginTop: 4, color: "#7A2A26" }}>{result.detail}</div>
        </div>
      )}
      <div style={{ fontSize: 12, color: "#9AA1AC", marginTop: 10 }}>PR ID: {result.id}</div>
    </div>
  );
}

function Field({ label, children }) {
  return <div style={{ marginBottom: 10 }}><label style={{ fontSize: 11.5, fontWeight: 600, color: "#6B7280", display: "block", marginBottom: 3 }}>{label}</label>{children}</div>;
}
const inputStyle = { width: "100%", padding: "8px 10px", border: `1px solid ${C.line}`, borderRadius: 7, fontSize: 13, boxSizing: "border-box", fontFamily: "inherit" };
const toggleBtn = { border: `1px solid ${C.line}`, background: "#fff", borderRadius: 7, padding: "6px 12px", fontSize: 12, cursor: "pointer" };
const toggleActive = { background: C.navy, color: "#fff", borderColor: C.navy };
/* ================= PURCHASE MANAGER QUEUE ================= */
function QueueTab({ prs, purchaseAdvance, cardStyle }) {
  const QUEUES = ["Auto-Approved PRs", "President-Approved Exceptions", "Ready for PO", "PO Issued", "Closed"];
  function mapQueue(p) {
    if (p.status === "Auto-Approved") return "Auto-Approved PRs";
    if (p.status === "President-Approved") return "President-Approved Exceptions";
    if (p.status === "Ready for PO") return "Ready for PO";
    if (p.status === "PO Issued") return "PO Issued";
    if (p.status === "Closed") return "Closed";
    return null;
  }
  const nextStatus = { "Auto-Approved PRs": "Ready for PO", "President-Approved Exceptions": "Ready for PO", "Ready for PO": "PO Issued", "PO Issued": "Closed" };
  return (
    <div>
      <div style={{ fontWeight: 700, marginBottom: 12, fontSize: 16 }}>Purchase Manager Work Queue</div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(260px,1fr))", gap: 14 }}>
        {QUEUES.map((q) => {
          const list = prs.filter((p) => mapQueue(p) === q);
          return (
            <div key={q} style={{ ...cardStyle }}>
              <div style={{ fontWeight: 700, fontSize: 12.5, marginBottom: 8, display: "flex", justifyContent: "space-between" }}>
                <span>{q}</span><Badge bg="#F0F0EF" fg="#6B7280">{list.length}</Badge>
              </div>
              {list.length === 0 && <div style={{ fontSize: 11.5, color: "#9AA1AC" }}>Empty</div>}
              {list.map((p) => (
                <div key={p.id} style={{ border: `1px solid ${C.line}`, borderRadius: 8, padding: 8, marginBottom: 8, fontSize: 12 }}>
                  <div style={{ fontWeight: 700 }}>{p.itemName}</div>
                  <div style={{ color: "#9AA1AC" }}>{p.id} · {fmtINR(p.value)}</div>
                  <div style={{ color: "#9AA1AC" }}>{fmtNum(p.requestedQty)} @ {fmtINR(p.requestedRate)}</div>
                  {p.vendorDetails && <div style={{ color: "#6B7280", marginTop: 2 }}>Vendor: {p.vendorDetails}</div>}
                  {p.proposedBrand && <div style={{ color: "#6B7280" }}>Brand: {p.proposedBrand}</div>}
                  {p.modelDetails && <div style={{ color: "#6B7280" }}>Model/spec: {p.modelDetails}</div>}
                  {nextStatus[q] && (
                    <button onClick={() => purchaseAdvance(p.id, nextStatus[q])} style={{ ...btnStyle(C.navy), fontSize: 11, padding: "4px 9px", marginTop: 6 }}>Move to {nextStatus[q]} →</button>
                  )}
                </div>
              ))}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ================= PRESIDENT'S EXCEPTION DESK ================= */
function ExceptionsTab({ pendingExceptions, presidentDecide, cardStyle, headCommitted, HEADS }) {
  return (
    <div>
      <div style={{ fontWeight: 700, fontSize: 16, marginBottom: 4 }}>President's Exception Desk</div>
      <div style={{ fontSize: 12.5, color: "#9AA1AC", marginBottom: 14 }}>Only genuine exceptions reach this screen. Everything within the frozen budget flows straight to the Purchase Manager.</div>
      {pendingExceptions.length === 0 && (
        <div style={{ ...cardStyle, textAlign: "center", color: "#9AA1AC", padding: 40 }}>No exceptions pending. The desk is clear.</div>
      )}
      {pendingExceptions.map((p) => {
        const head = HEADS.find((h) => h.name === p.headName);
        const catRemaining = head ? head.ceil - (headCommitted[head.name] || 0) : null;
        return (
          <div key={p.id} style={{ ...cardStyle, marginBottom: 14 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: C.gold, textTransform: "uppercase", letterSpacing: 0.5 }}>Why is this on my table?</div>
            <div style={{ fontSize: 16, fontWeight: 800, color: C.red, marginTop: 2 }}>{p.reasonCode}</div>
            <div style={{ fontSize: 13, color: "#6B7280", marginTop: 4 }}>{p.detail}</div>

            <table style={{ width: "100%", marginTop: 14, borderCollapse: "collapse", fontSize: 12.5 }}>
              <thead>
                <tr style={{ textAlign: "left", color: "#6B7280", fontSize: 10.5, textTransform: "uppercase" }}>
                  <th style={th}>Control</th><th style={th}>Frozen Budget</th><th style={th}>Current Request</th><th style={th}>Variance</th>
                </tr>
              </thead>
              <tbody>
                <tr style={{ borderTop: "1px solid #F0EFEA" }}><td style={th}>Quantity</td><td style={th}>{p.approvedQty !== null ? fmtNum(p.approvedQty) : "—"}</td><td style={th}>{fmtNum(p.requestedQty)}</td><td style={th}>{p.approvedQty !== null ? fmtNum(p.requestedQty - p.approvedQty) : "—"}</td></tr>
                <tr style={{ borderTop: "1px solid #F0EFEA" }}><td style={th}>Rate</td><td style={th}>{fmtINR(p.approvedRate)}</td><td style={th}>{fmtINR(p.requestedRate)}</td><td style={th}>{p.approvedRate ? `${(((p.requestedRate - p.approvedRate) / p.approvedRate) * 100).toFixed(2)}%` : "—"}</td></tr>
                <tr style={{ borderTop: "1px solid #F0EFEA" }}><td style={th}>Total Value</td><td style={th}>{catRemaining !== null ? fmtINR(catRemaining) + " avail." : "—"}</td><td style={th}>{fmtINR(p.value)}</td><td style={th}>{catRemaining !== null ? fmtINR(p.value - catRemaining) : "—"}</td></tr>
                <tr style={{ borderTop: "1px solid #F0EFEA" }}><td style={th}>Specification</td><td style={th}>{p.frozenSpec || "—"}</td><td style={th} colSpan={2}>{p.frozenSpec ? "As frozen" : "N/A"}</td></tr>
                <tr style={{ borderTop: "1px solid #F0EFEA" }}><td style={th}>Brand</td><td style={th}>—</td><td style={th} colSpan={2}>{p.proposedBrand || "Not specified"}</td></tr>
                <tr style={{ borderTop: "1px solid #F0EFEA" }}><td style={th}>Vendor</td><td style={th}>—</td><td style={th} colSpan={2}>{p.vendorDetails || "Not specified"}</td></tr>
                <tr style={{ borderTop: "1px solid #F0EFEA" }}><td style={th}>Model no. / item details</td><td style={th}>—</td><td style={th} colSpan={2}>{p.modelDetails || "Not specified"}</td></tr>
              </tbody>
            </table>

            <div style={{ display: "flex", gap: 18, marginTop: 12, fontSize: 12, flexWrap: "wrap" }}>
              <span>Budget head: <b>{p.headName}</b></span>
              <span>Requested by: <b>{p.requestedBy || "—"}</b> ({p.dept || "—"})</span>
              <span>Urgency: <b>{p.urgency}</b></span>
              <span>Required by: <b>{p.requiredBy || "—"}</b></span>
              <span>Available category balance: <b>{catRemaining !== null ? fmtINR(catRemaining) : "—"}</b></span>
            </div>
            {p.justification && <div style={{ marginTop: 8, fontSize: 12.5, color: "#6B7280", fontStyle: "italic" }}>"{p.justification}"</div>}

            <div style={{ display: "flex", gap: 8, marginTop: 14, flexWrap: "wrap" }}>
              <button onClick={() => presidentDecide(p.id, "Approve")} style={btnStyle(C.green)}>Approve</button>
              <button onClick={() => presidentDecide(p.id, "Approve with Conditions", "See remarks")} style={btnStyle(C.blue)}>Approve with Conditions</button>
              <button onClick={() => presidentDecide(p.id, "Return for Clarification")} style={btnStyle(C.amber)}>Return for Clarification</button>
              <button onClick={() => presidentDecide(p.id, "Defer")} style={btnStyle(C.grey)}>Defer</button>
              <button onClick={() => presidentDecide(p.id, "Reject")} style={btnStyle(C.red)}>Reject</button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* ================= AUDIT TRAIL ================= */
function AuditTab({ audit, cardStyle }) {
  return (
    <div style={{ ...cardStyle }}>
      <div style={{ fontWeight: 700, marginBottom: 4 }}>Audit Trail</div>
      <div style={{ fontSize: 12, color: "#9AA1AC", marginBottom: 14 }}>Non-editable history. Nothing here can be deleted.</div>
      {audit.map((a, i) => (
        <div key={i} style={{ display: "flex", gap: 12, padding: "9px 0", borderTop: i ? "1px solid #F0EFEA" : "none", fontSize: 12.5 }}>
          <div style={{ width: 150, flexShrink: 0, color: "#9AA1AC" }}>{a.ts}</div>
          <div style={{ width: 130, flexShrink: 0, fontWeight: 700 }}>{a.who}</div>
          <div>{a.text}</div>
        </div>
      ))}
    </div>
  );
}

/* ================= DEMO SCENARIOS ================= */
function DemoTab({ items, HEADS, headFreeze, freezeHead, setItemApproval, submitPR, setTab, cardStyle, tolerancePct }) {
  const [log, setLog] = useState([]);
  function run(fn, label) {
    const pr = fn();
    setLog((l) => [{ label, pr }, ...l]);
  }
  function findItem(name) { return items.find((i) => i.name === name); }

  const scenarios = [
    {
      title: "1 · Crockery item within qty & rate", desc: "Dinner plates — request exactly the frozen qty/rate.",
      run: () => { const it = findItem("Dinner plates — Banquet"); if (!it || it.freezeState === "Not Frozen") return null; return submitPR({ itemId: it.id, requestedQty: it.qty - (it.committedQty||0) > 0 ? Math.min(50, it.qty-(it.committedQty||0)) : 1, requestedRate: it.rate, requestedBy: "F&B Store Incharge", dept: "F&B", justification: "Replenishing opening crockery stock." }); },
    },
    {
      title: "2 · Cutlery 4% above frozen rate", desc: "Ap Knive (Banquet) — vendor quoted 4% higher; enough category budget remains.",
      run: () => { const it = findItem("Ap Knive (Banquet)"); if (!it || it.rate === null) return null; return submitPR({ itemId: it.id, requestedQty: 20, requestedRate: it.rate * 1.04, requestedBy: "F&B Store Incharge", dept: "F&B", justification: "Vendor rate revision, within tolerance." }); },
    },
    {
      title: "3 · Glassware 8% above frozen rate", desc: "Champagne Flute (Banquet) — vendor quoted 8% higher; exceeds tolerance → President.",
      run: () => { const it = findItem("Champagne Flute (Banquet)"); if (!it || it.rate === null) return null; return submitPR({ itemId: it.id, requestedQty: 20, requestedRate: it.rate * 1.0835, requestedBy: "F&B Store Incharge", dept: "F&B", justification: "Only vendor available quoted higher due to import glass pricing." }); },
    },
    {
      title: "4 · Unlisted operating item", desc: "An item that does not exist anywhere in the imported workbook, charged to Miscellaneous & Contingency.",
      run: () => submitPR({ itemId: null, unbudgetedName: "Portable PA system for lobby announcements", unbudgetedHead: "Miscellaneous & Contingency", requestedQty: 1, requestedRate: 18000, requestedBy: "Front Office Manager", dept: "Front Office", justification: "Not part of original CAPEX list; needed for soft-launch event." }),
    },
    {
      title: "5 · Room Linen — rate not frozen", desc: "Double Bedsheet has 3 competing vendor quotes; no single approved rate yet.",
      run: () => { const it = findItem("Double Bedsheet"); if (!it) return null; return submitPR({ itemId: it.id, requestedQty: 50, requestedRate: 1205, requestedBy: "Housekeeping Manager", dept: "Housekeeping", justification: "Urgent — required before soft opening." }); },
    },
    {
      title: "6 · Kitchen lump-sum item, unfrozen detail", desc: "A Kitchen Equipment wishlist item under the ₹25L lump-sum head, with no rate captured.",
      run: () => { const it = items.find((i) => i.head === "Kitchen Equipment & Utensils" && i.status !== "Complete"); if (!it) return null; return submitPR({ itemId: it.id, requestedQty: 1, requestedRate: 50000, requestedBy: "Executive Chef", dept: "Kitchen", justification: "Required for BOH readiness." }); },
    },
    {
      title: "7 · Category budget exhausted", desc: "Kitchen Equipment & Utensils is already over its ₹25L ceiling — even a small within-item PR is stopped.",
      run: () => { const it = findItem("Masala try 9 box"); if (!it) return null; return submitPR({ itemId: it.id, requestedQty: 5, requestedRate: it.rate, requestedBy: "Executive Chef", dept: "Kitchen", justification: "Additional stock for opening week." }); },
    },
  ];

  return (
    <div>
      <div style={{ ...cardStyle, marginBottom: 14 }}>
        <div style={{ fontWeight: 700, marginBottom: 4 }}>Setup: freeze the demo heads first</div>
        <div style={{ fontSize: 12.5, color: "#9AA1AC", marginBottom: 10 }}>Freezes Crockery, Cutlery, Glassware, Room Linen and Kitchen Equipment &amp; Utensils as "Fully Frozen" (Room Linen stays partially incomplete on purpose) so the scenarios below have something real to run against.</div>
        <button style={btnStyle(C.navy)} onClick={() => {
          ["Crockery", "Cutlery", "Glassware", "Kitchen Equipment & Utensils"].forEach((h) => freezeHead(h, "Fully Frozen"));
          freezeHead("Room Linen", "Provisionally Frozen");
        }}>Freeze demo budget heads</button>
        {" "}
        <span style={{ fontSize: 11.5, color: "#9AA1AC" }}>{Object.values(headFreeze).filter((s) => s !== "Not Frozen").length} of {HEADS.length} heads currently frozen.</span>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(300px,1fr))", gap: 12 }}>
        {scenarios.map((s) => (
          <div key={s.title} style={{ ...cardStyle }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>{s.title}</div>
            <div style={{ fontSize: 12, color: "#9AA1AC", margin: "6px 0 10px" }}>{s.desc}</div>
            <button style={btnStyle(C.gold)} onClick={() => run(s.run, s.title)}>Run scenario</button>
          </div>
        ))}
      </div>

      {log.length > 0 && (
        <div style={{ ...cardStyle, marginTop: 16 }}>
          <div style={{ fontWeight: 700, marginBottom: 10 }}>Scenario results (most recent first)</div>
          {log.map((l, i) => (
            <div key={i} style={{ borderTop: i ? "1px solid #F0EFEA" : "none", padding: "10px 0" }}>
              <div style={{ fontWeight: 700, fontSize: 12.5 }}>{l.label}</div>
              {!l.pr && <div style={{ fontSize: 12, color: C.red }}>Could not run — freeze the demo budget heads first.</div>}
              {l.pr && (
                <div style={{ fontSize: 12.5, marginTop: 4 }}>
                  <Badge bg={l.pr.autoApproved ? "#E9F6EF" : "#FCEAEA"} fg={l.pr.autoApproved ? C.green : C.red}>{l.pr.autoApproved ? "AUTO-APPROVED" : "ESCALATED: " + l.pr.reasonCode}</Badge>
                  <div style={{ color: "#6B7280", marginTop: 4 }}>{l.pr.detail}</div>
                </div>
              )}
            </div>
          ))}
          <button onClick={() => setTab("exceptions")} style={{ ...btnStyle(C.navy), marginTop: 10 }}>View escalations on President's desk →</button>
        </div>
      )}
    </div>
  );
}
